package com.diberlog.jarvis.mobile;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class ThemeChatTests {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();
    MainActivity open(){return (MainActivity)i.startActivitySync(new Intent(i.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
    void removeChat(MainActivity a,String id)throws Exception{JSONArray chats=MobileStore.chats(a);for(int n=chats.length()-1;n>=0;n--)if(chats.getJSONObject(n).getString("id").equals(id))chats.remove(n);MobileStore.saveChats(a,chats);ChatDrafts.write(a,id,"",new JSONArray());}
    @Test public void plusSelectsDocumentAndDoesNotCreateAnotherChat()throws Exception{MainActivity a=open();IntentFilter picker=new IntentFilter(Intent.ACTION_OPEN_DOCUMENT);picker.addCategory(Intent.CATEGORY_OPENABLE);picker.addDataType("*/*");Instrumentation.ActivityMonitor monitor=i.addMonitor(picker,new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null),true);try{i.runOnMainSync(()->a.show(1));int count=MobileStore.chats(a).length();i.runOnMainSync(()->{assertTrue(a.shell.findViewWithTag("Прикрепить документ").performClick());});assertEquals(1,monitor.getHits());assertEquals(count,MobileStore.chats(a).length());}finally{i.removeMonitor(monitor);i.runOnMainSync(a::finish);}}
    @Test public void attachedWordAndDraftSurviveActivityRestartWithoutSending()throws Exception{MainActivity a=open();String id="";android.net.Uri uri=null;try{
        i.runOnMainSync(()->{a.show(1);a.newChat();a.input.setText("Вымышленный вопрос про документ");a.saveDraft();});id=a.chatId;ContentValues values=new ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"fixture-document.docx");values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"application/vnd.openxmlformats-officedocument.wordprocessingml.document");uri=a.getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);assertNotNull(uri);try(java.io.OutputStream out=a.getContentResolver().openOutputStream(uri)){ChatDocuments.writeDocx(out,"Вымышленный текст документа, не секрет пользователя");}
        android.net.Uri selected=uri;i.runOnMainSync(()->{a.documents.attaching=true;a.documents.attachmentChatId=a.chatId;a.documents.result(10,Activity.RESULT_OK,new Intent().setData(selected));});for(int n=0;n<50&&ChatDrafts.read(a,id).getJSONArray("attachments").length()==0;n++)Thread.sleep(100);assertEquals("fixture-document.docx",ChatDrafts.read(a,id).getJSONArray("attachments").getJSONObject(0).getString("name"));assertEquals(0,a.activeChat().getJSONArray("messages").length());assertTrue(ChatDrafts.prompt("Проверь документ",ChatDrafts.read(a,id).getJSONArray("attachments")).contains("Вымышленный текст"));i.runOnMainSync(a::finish);
        MainActivity restarted=open();try{i.runOnMainSync(()->restarted.show(1));assertEquals(id,restarted.chatId);assertEquals("Вымышленный вопрос про документ",restarted.input.getText().toString());assertEquals(1,restarted.attachments.length());assertEquals(0,restarted.activeChat().getJSONArray("messages").length());}finally{i.runOnMainSync(restarted::finish);}
    }finally{if(uri!=null)a.getContentResolver().delete(uri,null,null);if(!id.isEmpty())removeChat(a,id);i.runOnMainSync(a::finish);}}
    @Test public void chatOwnReplySavesAndConcurrentEditIsNotOverwritten()throws Exception{MainActivity a=open();String id="";try{i.runOnMainSync(()->{a.show(1);a.newChat();});JSONObject chat=a.activeChat();id=chat.getString("id");chat.getJSONArray("messages").put(new JSONObject().put("role","user").put("content","Вымышленный вопрос"));MobileStore.saveChat(a,chat);chat.getJSONArray("messages").put(new JSONObject().put("role","assistant").put("content","Вымышленный ответ"));MobileStore.saveChat(a,chat);assertEquals(2,a.activeChat().getJSONArray("messages").length());JSONObject stale=a.activeChat(),other=a.activeChat();other.put("title","Изменено другим клиентом");MobileStore.saveChat(a,other);assertEquals("Изменено другим клиентом",a.activeChat().getString("title"));java.lang.reflect.Field editField=MobileStore.class.getDeclaredField("EDITS");editField.setAccessible(true);java.util.Map<?,?> edits=(java.util.Map<?,?>)editField.get(null);assertNotNull("Original chat edit baseline must exist",edits.get(stale));stale.put("title","Устаревшая версия");try{MobileStore.saveChat(a,stale);fail("Stale chat overwrote another edit");}catch(JSONException expected){}assertEquals("Изменено другим клиентом",a.activeChat().getString("title"));}finally{if(!id.isEmpty())removeChat(a,id);i.runOnMainSync(a::finish);}}
    @Test public void themesCoverNativeAndWebEditorsAndKeepSessionKey()throws Exception{MainActivity a=open();String old=a.prefs.getString("appearance","dark"),noteId="theme-note-"+java.util.UUID.randomUUID();try{JSONObject center=MobileStore.center(a);center.getJSONArray("notes").put(new JSONObject().put("id",noteId).put("title","План на день").put("text","Вымышленная заметка для проверки читаемости").put("type","text").put("format","plain").put("updatedAt",MobileStore.now()));MobileStore.save(a,center);i.runOnMainSync(()->{a.show(13);a.apiKey="fixture-session-key";MobileTheme.choose(a,"light");assertEquals(Color.parseColor("#F1F5F4"),MainActivity.BG);assertEquals("fixture-session-key",a.apiKey);a.show(3);});assertTrue(PolishTests.waitJs(i,a,"document.documentElement.dataset.theme==='light'"));assertTrue(PolishTests.waitJs(i,a,"(()=>{const b=document.querySelector('.note-list button');if(!b)return false;b.click();return Boolean(document.querySelector('.note-list button.active'));})()"));PolishTests.shot(i,a,"preview-notes-light.png");i.runOnMainSync(()->{a.show(13);MobileTheme.choose(a,"dark");assertEquals("fixture-session-key",a.apiKey);a.show(3);});assertTrue(PolishTests.waitJs(i,a,"document.documentElement.dataset.theme==='dark'"));assertTrue(PolishTests.waitJs(i,a,"(()=>{const b=document.querySelector('.note-list button');if(!b)return false;b.click();return Boolean(document.querySelector('.note-list button.active'));})()"));PolishTests.shot(i,a,"preview-notes-dark.png");i.runOnMainSync(()->{a.show(13);MobileTheme.choose(a,"system");assertEquals("system",a.prefs.getString("appearance",""));});}finally{JSONObject center=MobileStore.center(a);JSONArray notes=center.getJSONArray("notes");for(int n=notes.length()-1;n>=0;n--)if(notes.getJSONObject(n).optString("id").equals(noteId))notes.remove(n);MobileStore.save(a,center);a.prefs.edit().putString("appearance",old).apply();i.runOnMainSync(a::finish);}}
    @Test public void launcherHasExplicitDarkAdaptiveBackground(){MainActivity a=open();try{Drawable icon=a.getApplicationInfo().loadIcon(a.getPackageManager());assertTrue(icon instanceof AdaptiveIconDrawable);Drawable background=((AdaptiveIconDrawable)icon).getBackground();assertTrue(background instanceof ColorDrawable);assertEquals(Color.rgb(16,19,21),((ColorDrawable)background).getColor());}finally{i.runOnMainSync(a::finish);}}
}
